     1→#!/usr/bin/env perl
     2→# ABOUTME: Test Sea of Nodes Chapter 7 - While Loops
     3→# ABOUTME: Validates loop IR nodes, loop phi nodes, and basic while loop semantics
     4→
     5→use 5.42.0;
     6→use Test2::V0;
