    18→subtest 'Loop node creation' => sub {
    19→    my $graph = Chalk::IR::Graph->new();
    20→    my $start = Chalk::IR::Node->new(
    21→        id => 1,
    22→        op => 'Start',
    23→        inputs => [],
    24→        attributes => {},
    25→    );
    26→    $graph->add_node($start);
    27→
    28→    # Loop node is like Region but for loops
    29→    my $loop = Chalk::IR::Node->new(
    30→        id => 2,
    31→        op => 'Loop',
    32→        inputs => [$start->id],  # Entry control
    33→        attributes => {},
