    35→    $graph->add_node($loop);
    36→
    37→    is $loop->op, 'Loop', 'Loop node created';
    38→    is scalar($loop->inputs->@*), 1, 'Loop has entry control';
    39→
    40→    # Add backedge later (lazy phi pattern)
    41→    push $loop->inputs->@*, 3;  # Backedge from loop body
    42→    is scalar($loop->inputs->@*), 2, 'Loop can add backedge';
    43→};
    44→
    45→subtest 'Loop phi node creation' => sub {
    46→    my $graph = Chalk::IR::Graph->new();
    47→    my $start = Chalk::IR::Node->new(
    48→        id => 1,
    49→        op => 'Start',
    50→        inputs => [],
    51→        attributes => {},
    52→    );
    53→    $graph->add_node($start);
