    59→        attributes => {},
    60→    );
    61→    $graph->add_node($loop);
    62→
    63→    # Loop phi has initial value and placeholder for backedge
    64→    my $phi = Chalk::IR::Node->new(
    65→        id => 3,
    66→        op => 'Phi',
    67→        inputs => [$loop->id, 0],  # Control, initial value
    68→        attributes => {},
    69→    );
    70→    $graph->add_node($phi);
    71→
    72→    is $phi->op, 'Phi', 'Loop phi node created';
    73→    is scalar($phi->inputs->@*), 2, 'Loop phi has control and initial value';
    74→
    75→    # Add loop value later
    76→    push $phi->inputs->@*, 10;  # Loop update value
    77→    is scalar($phi->inputs->@*), 3, 'Loop phi can add loop value';
    78→};
    79→
    80→subtest 'Simple while(true) infinite loop IR' => sub {
    81→    # while (true) { }
    82→    my $graph = Chalk::IR::Graph->new();
    83→
    84→    my $start = Chalk::IR::Node->new(
    85→        id => 1,
    86→        op => 'Start',
    87→        inputs => [],
    88→        attributes => {},
    89→    );
    90→    $graph->add_node($start);
    91→
    92→    my $loop = Chalk::IR::Node->new(
    93→        id => 2,
    94→        op => 'Loop',
    95→        inputs => [$start->id],  # Entry
    96→        attributes => {},
    97→    );
    98→    $graph->add_node($loop);
    99→
   100→    my $const_true = Chalk::IR::Node->new(
   101→        id => 3,
   102→        op => 'Constant',
   103→        inputs => [],
   104→        attributes => { value => 1 },
   105→    );
   106→    $graph->add_node($const_true);
   107→
   108→    my $if_node = Chalk::IR::Node->new(
   109→        id => 4,
   110→        op => 'If',
   111→        inputs => [$loop->id, $const_true->id],
   112→        attributes => {},
   113→    );
   114→    $graph->add_node($if_node);
