   116→    my $proj_true = Chalk::IR::Node->new(
   117→        id => 5,
   118→        op => 'Proj',
   119→        inputs => [$if_node->id],
   120→        attributes => { index => 0 },
   121→    );
   122→    $graph->add_node($proj_true);
   123→
   124→    my $proj_false = Chalk::IR::Node->new(
   125→        id => 6,
   126→        op => 'Proj',
   127→        inputs => [$if_node->id],
   128→        attributes => { index => 1 },
   129→    );
   130→    $graph->add_node($proj_false);
   131→
   132→    # Backedge to loop
   133→    push $loop->inputs->@*, $proj_true->id;
   134→
   135→    # Exit through false branch
   136→    my $return_node = Chalk::IR::Node->new(
   137→        id => 7,
   138→        op => 'Return',
   139→        inputs => [$proj_false->id, 0],
   140→        attributes => {},
   141→    );
   142→    $graph->add_node($return_node);
