   144→    is scalar($loop->inputs->@*), 2, 'Loop has entry and backedge';
   145→    my $json = $graph->to_json();
   146→    my $has_loop = scalar(grep { $_->{op} eq 'Loop' } $json->{nodes}->@*);
   147→    ok $has_loop, 'IR contains Loop node';
