                    $dom{$node_id} = $new_idom;
                    $changed = 1;
                }
                elsif ($dom{$node_id} ne $new_idom) {
                    $dom{$node_id} = $new_idom;
                    $changed = 1;
                }
            }
        }

        return \%dom;
    }

    # Helper: Find intersection of two nodes in dominance tree
    method _intersect($dom, $b1, $b2) {
        my $finger1 = $b1;
        my $finger2 = $b2;

