            # Move up dominance tree
            while ($self->_node_depth($finger1) > $self->_node_depth($finger2)) {
                $finger1 = $dom->{$finger1};
                last unless defined($finger1);
            }
            last unless defined($finger1);

            while ($self->_node_depth($finger2) > $self->_node_depth($finger1)) {
