# Build IR from a simple Perl expression/statement
# For now, this handles the patterns we see in chapter examples
method build_from_code($code) {
    # Create Start node
    my $start = Chalk::IR::Node->new(
        id => $self->next_node_id(),
        op => 'Start',
        inputs => [],
        attributes => { function => 'main' }
    );
    $graph->add_node($start);
    $self->set_control($start->id);

    # Parse the code pattern and build IR
    # For Chapter 1: just "return 42;"
    if ($code =~ /^\\s*return\\s+(\\d+)\\s*;\\s*$/) {
        my $value = $1;

        # Create Constant node
        my $constant = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Constant',
            inputs => [$start->id],
            attributes => { value => $value + 0, type => 'Int' }
        );
        $graph->add_node($constant);

        # Create Return node
        my $return = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Return',
            inputs => [$current_control, $constant->id],
            attributes => {}
        );
        $graph->add_node($return);
    }
    # For Chapter 2: "return 1 + 2 * 3;"
    # This is a specific pattern - need proper parser for general case
    elsif ($code =~ /^\\s*return\\s+(\\d+)\\s*\\+\\s*(\\d+)\\s*\\*\\s*(\\d+)\\s*;\\s*$/) {
        my ($left, $mul_left, $mul_right) = ($1, $2, $3);

        # Create Multiply node: mul_left * mul_right
        my $mul = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Multiply',
            inputs => [$start->id],
            attributes => {
                left => { op => 'Constant', value => $mul_left + 0, type => 'Int' },
                right => { op => 'Constant', value => $mul_right + 0, type => 'Int' },
            }
        );
        $graph->add_node($mul);

        # Create Add node: left + (multiply result)
        my $add = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Add',
            inputs => [$start->id, $mul->id],
            attributes => {
                left => { op => 'Constant', value => $left + 0, type => 'Int' },
                right => { op => 'NodeRef', node_id => $mul->id },
            }
        );
        $graph->add_node($add);

        # Create Return node
        my $return = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Return',
            inputs => [$current_control, $add->id],
            attributes => {}
        );
        $graph->add_node($return);
    }

    return $graph;
}

