    my $load = Chalk::IR::Node->new(
        id => 'node_2',
        op => 'Load',
        inputs => ['node_0', 'node_1'],
        attributes => {
            name => '$x',
            store_id => 'node_1'
        }
    );
    $graph->add_node($load);

    # Create Multiply node: $x * 2
