    17→        # If self has value 0 (is add_id), return other
    18→        if ($value == 0) {
    19→            return $other;
    20→        }
    21→
    22→        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
    23→        # This handles the case where we update the chart after evaluation
    24→        my $self_focus = $self->context->focus;
    25→        my $other_focus = $other->context->focus;
    26→
    27→        if (!defined($self_focus) && defined($other_focus)) {
    28→            return $other;
    29→        }
    30→        if (defined($self_focus) && !defined($other_focus)) {
    31→            return $self;
    32→        }
    33→
    34→        # For semantic values, prefer the alternative with more children
    35→        # (this handles ambiguous parses - we want the one that consumed more input)
    36→        my $self_children = scalar(@{$self->context->children});
    37→        my $other_children = scalar(@{$other->context->children});
    38→
    39→        if ($other_children > $self_children) {
    40→            return $other;
    41→        }
