    70→        return 0 unless ref($other) eq ref($self);
    71→        # Use refaddr for reference equality to avoid recursion
    72→        # For semantic semiring, we want elements to be considered non-equal
    73→        # to add_id unless they are literally the same object
    74→        return refaddr($self) == refaddr($other) ? 1 : 0;
