# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
# ABOUTME: Walks parse trees and generates IR graphs with proper SSA form, control flow, and data dependencies
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;

class Chalk::IR::Builder {
    use Chalk::IR::Node;
    use Chalk::IR::Graph;
    use Chalk::IR::Scope;

    field $graph :reader;
    field $scope :reader;
    field $node_counter :reader = 0;
    field $current_control :reader;  # Current control flow node

    ADJUST {
        $graph = Chalk::IR::Graph->new();
        $scope = Chalk::IR::Scope->new();
    }

    # Generate unique node ID
    method next_node_id() {
        my $id = "node_$node_counter";
        $node_counter++;
        return $id;
    }

    # Set current control flow node
    method set_control($ctrl) {
        $current_control = $ctrl;
    }

    # Build IR from simple code patterns
    # LIMITATION: This method uses pattern matching for simple examples (Chapters 1-4).
    # For complex control flow (Chapters 5-11: if/while/loops/calls), full parser integration
    # via build_from_parse() is needed. See GitHub issue for semantic actions implementation.
    method build_from_code($code) {
        # Create Start node
        my $start = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Start',
            inputs => [],
            attributes => { function => 'main' }
        );
        $graph->add_node($start);
        $self->set_control($start->id);

        # Parse the code pattern and build IR
        # For Chapter 1: just "return 42;"
        if ($code =~ /^\s*return\s+(\d+)\s*;\s*$/) {
            my $value = $1;

            # Create Constant node
            my $constant = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Constant',
                inputs => [$start->id],
                attributes => { value => $value + 0, type => 'Int' }
            );
            $graph->add_node($constant);

            # Create Return node
            my $return = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Return',
                inputs => [$current_control, $constant->id],
                attributes => {}
            );
            $graph->add_node($return);
        }
        # For Chapter 2: "return 1 + 2 * 3;" (specific pattern for operator precedence)
        # Respects precedence: multiplication before addition
        elsif ($code =~ /^\s*return\s+(\d+)\s*\+\s*(\d+)\s*\*\s*(\d+)\s*;\s*$/) {
            my ($left, $mul_left, $mul_right) = ($1, $2, $3);

            # Create Multiply node: mul_left * mul_right
            my $mul = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Multiply',
                inputs => [$start->id],
                attributes => {
                    left => { op => 'Constant', value => $mul_left + 0, type => 'Int' },
                    right => { op => 'Constant', value => $mul_right + 0, type => 'Int' },
                }
            );
            $graph->add_node($mul);

            # Create Add node: left + (multiply result)
            my $add = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Add',
                inputs => [$start->id, $mul->id],
                attributes => {
                    left => { op => 'Constant', value => $left + 0, type => 'Int' },
                    right => { op => 'NodeRef', node_id => $mul->id },
                }
            );
            $graph->add_node($add);

            # Create Return node
            my $return = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Return',
                inputs => [$current_control, $add->id],
                attributes => {}
            );
            $graph->add_node($return);
        }
        # For Chapter 3: "my $x = 5; return $x * 2;" (variable declaration and use)
        elsif ($code =~ /^\s*my\s+(\$\w+)\s*=\s*(\d+)\s*;\s*return\s+\1\s*\*\s*(\d+)\s*;\s*$/) {
            my ($var, $init_value, $mul_value) = ($1, $2, $3);

            # Create Store node: my $var = init_value
            my $store = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Store',
                inputs => [$start->id],
                attributes => {
                    name => $var,
                    value => { op => 'Constant', value => $init_value + 0, type => 'Int' }
                }
            );
            $graph->add_node($store);
            $scope->define($var, $store->id);

            # Create Load node: read $var
            my $load = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Load',
                inputs => [$start->id, $store->id],
                attributes => {
                    name => $var,
                    store_id => $store->id
                }
            );
            $graph->add_node($load);

            # Create Multiply node: $var * mul_value
            my $mul = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Multiply',
                inputs => [$start->id, $load->id],
                attributes => {
                    left => { op => 'NodeRef', node_id => $load->id },
                    right => { op => 'Constant', value => $mul_value + 0, type => 'Int' }
                }
            );
            $graph->add_node($mul);

            # Create Return node
            my $return = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Return',
                inputs => [$current_control, $mul->id],
                attributes => {}
            );
            $graph->add_node($return);
        }
        # For Chapter 4: "method name($param) { return $param + value; }"
        elsif ($code =~ /^\s*method\s+(\w+)\s*\((\$\w+)\)\s*\{\s*return\s+\2\s*\+\s*(\d+)\s*;\s*\}\s*$/) {
            my ($method_name, $param, $add_value) = ($1, $2, $3);

            # Update Start node with params
            $start = Chalk::IR::Node->new(
                id => 'node_0',
                op => 'Start',
                inputs => [],
                attributes => {
                    function => $method_name,
                    params => [$param]
                }
            );
            # Replace the Start node in the graph
            $graph = Chalk::IR::Graph->new();
            $graph->add_node($start);

            # Create control projection ($ctrl)
            my $ctrl = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Proj',
                inputs => [$start->id],
                attributes => { index => 0, label => '$ctrl' }
            );
            $graph->add_node($ctrl);
            $scope->define('$ctrl', $ctrl->id);
            $self->set_control($ctrl->id);

            # Create parameter projection
            my $arg_proj = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Proj',
                inputs => [$start->id],
                attributes => { index => 1, label => $param }
            );
            $graph->add_node($arg_proj);
            $scope->define($param, $arg_proj->id);

            # Create Add node: $param + add_value
            my $add = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Add',
                inputs => [$ctrl->id, $arg_proj->id],
                attributes => {
                    left => { op => 'NodeRef', node_id => $arg_proj->id },
                    right => { op => 'Constant', value => $add_value + 0, type => 'Int' }
                }
            );
            $graph->add_node($add);

            # Create Return node
            my $return = Chalk::IR::Node->new(
                id => $self->next_node_id(),
                op => 'Return',
                inputs => [$ctrl->id, $add->id],
                attributes => {}
            );
            $graph->add_node($return);
        }

        return $graph;
    }

    # Build IR from a parse tree (future - for semantic integration)
    method build_from_parse($parse_tree) {
        # TODO: Walk parse tree and generate IR
        # For now, return empty graph as placeholder
        return $graph;
    }
}

