#!/usr/bin/env perl
use 5.42.0;
use lib 'lib';
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::IR::Builder;
use Chalk::Semiring::Semantic;
use Data::Dumper;

# Load chalk.bnf grammar with semantic actions
open my $fh, '<:utf8', 'grammar/chalk.bnf' or die $!;
my $bnf_content = do { local $/; <$fh> };
close $fh;

my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');

# Create IR builder
my $builder = Chalk::IR::Builder->new();

# Initialize Start node
$builder->build_start_node('main');

# Create environment with builder
my %env = (
    ir_builder => $builder
);

# Create semantic semiring with builder in environment
my $semiring = Chalk::Semiring::Semantic->new(
    env => \%env,
    grammar => $grammar
);

# Create parser with semantic semiring
my $parser = Chalk::Parser->new(
    grammar => $grammar,
    semiring => $semiring
);

# Parse Chapter 3 code: my $x = 5; return $x * 2;
my $code = "my \$x = 5; return \$x * 2;";
print "Parsing: $code\n";

my $result = $parser->parse_string($code);

if ($result) {
    print "Parse succeeded!\n";

    # Get the IR graph from builder
    my $graph = $builder->graph;
    print "Total graph nodes: ", $graph->node_count, "\n\n";

    print "All nodes:\n";
    for my $node_id (sort keys %{$graph->nodes}) {
        my $node = $graph->nodes->{$node_id};
        print "  $node_id: ", $node->op;
        if ($node->op eq 'Constant') {
            print " (value: ", $node->attributes->{value}, ")";
        } elsif ($node->op eq 'Store') {
            print " (name: ", $node->attributes->{name}, ")";
        } elsif ($node->op eq 'Load') {
            print " (name: ", $node->attributes->{name}, ")";
        }
        print "\n";
        print "    inputs: [", join(", ", $node->inputs->@*), "]\n";
    }
} else {
    print "Parse failed!\n";
}

