#!/usr/bin/env perl
use 5.42.0;
use lib 'lib';
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::IR::Builder;
use Chalk::Semiring::Semantic;

# Load chalk.bnf grammar with semantic actions
open my $fh, '<:utf8', 'grammar/chalk.bnf' or die $!;
my $bnf_content = do { local $/; <$fh> };
close $fh;

my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');

# Create IR builder
my $builder = Chalk::IR::Builder->new();

# Initialize Start node with parameters (simulating method calculate($arg))
$builder->build_start_node('calculate', ['arg']);

# Create environment with builder
my %env = (
    ir_builder => $builder
);

# Create semantic semiring
my $semiring = Chalk::Semiring::Semantic->new(
    env => \%env,
    grammar => $grammar
);

# Create parser
my $parser = Chalk::Parser->new(
    grammar => $grammar,
    semiring => $semiring
);

# Parse method body: return $arg + 10;
my $code = "return \$arg + 10;";
print "Parsing: $code\n";
print "(with parameter: arg)\n\n";

my $result = $parser->parse_string($code);

if ($result) {
    print "Parse succeeded!\n";

    # Get the IR graph
    my $graph = $builder->graph;
    print "Total graph nodes: ", $graph->node_count, "\n\n";

    print "All nodes:\n";
    for my $node_id (sort keys %{$graph->nodes}) {
        my $node = $graph->nodes->{$node_id};
        print "  $node_id: ", $node->op;
        if ($node->op eq 'Constant') {
            print " (value: ", $node->attributes->{value}, ")";
        } elsif ($node->op eq 'Proj') {
            print " (label: ", $node->attributes->{label}, ", index: ", $node->attributes->{index}, ")";
        }
        print "\n";
        print "    inputs: [", join(", ", $node->inputs->@*), "]\n";
    }

    # Find final Return
    my @return_nodes = grep { $graph->nodes->{$_}->op eq 'Return' } keys %{$graph->nodes};
    if (@return_nodes) {
        my $final_return = (sort @return_nodes)[-1];
        print "\nFinal Return node: $final_return\n";

        # Walk graph
        my %reachable;
        my @to_visit = ($final_return);
        while (@to_visit) {
            my $node_id = shift @to_visit;
            next if $reachable{$node_id};
            $reachable{$node_id} = 1;

            my $node = $graph->nodes->{$node_id};
            push @to_visit, $node->inputs->@*;
        }

        print "\nReachable nodes (final IR):\n";
        for my $node_id (sort keys %reachable) {
            my $node = $graph->nodes->{$node_id};
            print "  $node_id: ", $node->op;
            if ($node->op eq 'Constant') {
                print " (value: ", $node->attributes->{value}, ")";
            } elsif ($node->op eq 'Proj') {
                print " (label: ", $node->attributes->{label}, ")";
            }
            print "\n";
        }
    }
} else {
    print "Parse failed!\n";
}

