my $comparison = $builder2->build_greater_node($param_x, $zero);

# Build If structure
my $if_node = $builder2->build_if_node($comparison);
my $if_true = $builder2->build_if_true_node($if_node);
my $if_false = $builder2->build_if_false_node($if_node);

# True branch: return 1
$builder2->set_control($if_true->id);
my $one = $builder2->build_constant_node(1);
my $return_true = $builder2->build_return_node($one);

# False branch: return 0
$builder2->set_control($if_false->id);
my $return_false = $builder2->build_return_node($zero);

print "Manually constructed IR for:\n";
print "  if (\$x > 0) { return 1; }\n";
