        inputs => ['node_0', 'node_2'],
        attributes => {
            left => { op => 'NodeRef', node_id => 'node_2' },
            right => { op => 'Constant', value => 2, type => 'Int' }
        }
    );
    $graph->add_node($mul);

    # Create Return node
    my $return = Chalk::IR::Node->new(
        id => 'node_4',
        op => 'Return',
        inputs => ['node_0', 'node_3'],
        attributes => {}
    );
