    $graph->add_node($ctrl);

    my $arg = Chalk::IR::Node->new(
        id => 'node_2',
        op => 'Proj',
        inputs => ['node_0'],
        attributes => { index => 1, label => '$arg' }
    );
    $graph->add_node($arg);

    my $add = Chalk::IR::Node->new(
        id => 'node_3',
        op => 'Add',
        inputs => ['node_1', 'node_2'],
