        op => 'Start',
        inputs => [],
        attributes => {
            function => 'calculate',
            params => ['$arg']
        }
    );
    $graph->add_node($start);

    # Control projection ($ctrl)
    my $ctrl = Chalk::IR::Node->new(
        id => 'node_1',
        op => 'Proj',
        inputs => ['node_0'],
        attributes => { index => 0, label => '$ctrl' }
    );
    $graph->add_node($ctrl);
    $scope->define('$ctrl', 'node_1');

    # Parameter projection ($arg)
    my $arg = Chalk::IR::Node->new(
        id => 'node_2',
        op => 'Proj',
        inputs => ['node_0'],
        attributes => { index => 1, label => '$arg' }
