    is($arg_node->op, 'Proj', 'Arg node is Proj');
    is($arg_node->attributes->{index}, 1, 'Arg has index 1');
    is($arg_node->attributes->{label}, '$arg', 'Arg has label $arg');

    # Verify Add node ($arg + 10)
