# ABOUTME: Semantic action for Block - wires up control flow between statements
# ABOUTME: Chains statement control edges and returns last statement for parent to wire up

use 5.42.0;
use experimental 'class';
use Scalar::Util qw(blessed);

class Chalk::Grammar::Chalk::Rule::Block :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        # Block -> '{' WS_OPT Statements WS_OPT '}'
        # Statements is a list of Statement nodes

        my $builder = $context->env->{ir_builder};
        return undef unless $builder;

        # Get Statements (child 2)
        my $statements = $context->child(2);
        return undef unless $statements;

        # Statements might be a single node or an array of nodes
        my @stmt_nodes;
        if (ref($statements) eq 'ARRAY') {
            @stmt_nodes = grep { blessed($_) && $_->can('id') } @$statements;
        } elsif (blessed($statements) && $statements->can('id')) {
            @stmt_nodes = ($statements);
        }

        return undef unless @stmt_nodes;

        # Get entry control (either current_control or placeholder from parent)
        my $entry_control = $builder->current_control;

        # Wire up control between statements
        my $current_ctrl = $entry_control;
        for my $stmt (@stmt_nodes) {
            # Replace placeholder with actual control
            if ($stmt->inputs->[0] eq '__CONTROL_PLACEHOLDER__') {
                $builder->set_node_control($stmt, $current_ctrl);
            }
            # Next statement starts with this statement's output control
            $current_ctrl = $stmt->id;
        }

        # Update builder's current control to exit of last statement
        $builder->set_control($current_ctrl);

        # Return last statement (its control output is the block's exit)
        return $stmt_nodes[-1];
    }
}

1;

