# ABOUTME: Semantic action for ConditionalStatement - builds If/IfTrue/IfFalse/Region IR structure
# ABOUTME: Handles if/elsif/else control flow with proper Region merging and Phi nodes

use 5.42.0;
use experimental 'class';
use Scalar::Util qw(blessed);

class Chalk::Grammar::Chalk::Rule::ConditionalStatement :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        # ConditionalStatement has several alternatives:
        # 1. if (expr) block
        # 2. if (expr) block else block
        # 3. if (expr) block elsif (expr) block
        # 4. if (expr) block elsif (expr) block else block

        # NOTE: This semantic action has a fundamental limitation with the current
        # bottom-up parsing architecture. By the time evaluate() is called, child
        # Blocks have already been parsed with the current control flow context.
        # This means we cannot properly manage control flow during parsing.
        #
        # For proper control flow support, we need either:
        # 1. Multi-pass compilation (parse to AST, then generate IR)
        # 2. Top-down attribute evaluation
        # 3. Different parsing strategy (e.g., recursive descent with IR generation)
        #
        # For now, this semantic action creates the IR structure but the Block
        # statements won't use the correct control flow edges.

        my @children = $context->children->@*;
        my $builder = $context->env->{ir_builder};
        return undef unless $builder;

        # Save current control
        my $entry_control = $builder->current_control;

        # Find 'if' keyword position (should be at start)
        my $keyword_index = 0;

        # Parse: if WS_OPT ( WS_OPT Expression WS_OPT ) WS_OPT Block
        # Indices: 0    1    2   3      4          5    6   7     8

        my $condition = $context->child(4);  # Expression
        return undef unless (blessed($condition) && $condition->can('id'));

        # Build If node
        my $if_node = $builder->build_if_node($condition);
        my $if_true = $builder->build_if_true_node($if_node);
        my $if_false = $builder->build_if_false_node($if_node);

        # Parse true branch with IfTrue control
        $builder->set_control($if_true->id);
        my $true_block = $context->child(8);  # Block
        my $true_control = $builder->current_control;

        # Check for else/elsif
        my $has_else = 0;
        my $has_elsif = 0;
        my $false_control = $if_false->id;

        # Look for 'else' or 'elsif' after the first block
        if (@children > 10) {
            my $next_keyword = $children[10]->extract;
            if (defined $next_keyword && $next_keyword eq 'else') {
                $has_else = 1;
                # Parse else block with IfFalse control
                $builder->set_control($if_false->id);
                my $else_block = $context->child(12);  # else Block
                $false_control = $builder->current_control;
            }
            elsif (defined $next_keyword && $next_keyword eq 'elsif') {
                $has_elsif = 1;
                # For now, treat elsif as nested if in false branch
                # TODO: Implement full elsif chain
                $builder->set_control($if_false->id);
                # Parse the elsif as a new conditional
                my $elsif_expr = $context->child(14);  # elsif expression
                # This would need recursive handling...
                $false_control = $builder->current_control;
            }
        }
        else {
            # No else branch - false path just falls through
            $false_control = $if_false->id;
        }

        # Build Region to merge control paths
        my $region = $builder->build_region_node($true_control, $false_control);
        $builder->set_control($region->id);

        # Return the Region node (represents the merge point)
        return $region;
    }
}

1;

