     1→# ABOUTME: Semantic action for VariableDeclaration - creates Store IR nodes for variable assignments
     2→# ABOUTME: VariableDeclaration handles my/our/state variable declarations with initialization
     3→
     4→use 5.42.0;
     5→use experimental 'class';
     6→
     7→class Chalk::Grammar::Chalk::Rule::VariableDeclaration :isa(Chalk::GrammarRule) {
     8→    method evaluate($context) {
     9→        # VariableDeclaration -> LexicalDeclarator WS_OPT Variable
    10→        # VariableDeclaration -> LexicalDeclarator WS_OPT Variable WS_OPT AttributeList
    11→        # VariableDeclaration -> LexicalDeclarator WS_OPT Variable WS_OPT '=' WS_OPT Expression
    12→        # VariableDeclaration -> LexicalDeclarator WS_OPT Variable WS_OPT AttributeList WS_OPT '=' WS_OPT Expression
    13→        # VariableDeclaration -> LexicalDeclarator WS_OPT '(' WS_OPT VariableList WS_OPT ')' WS_OPT '=' WS_OPT Expression
    14→
    15→        my $builder = $context->env->{ir_builder};
    16→        my @children = $context->children->@*;
    17→
    18→        # Find the '=' to determine if this is an initialized declaration
    19→        my $has_init = 0;
    20→        my $equals_index = -1;
    21→        for my $i (0..$#children) {
    22→            my $child = $children[$i]->extract;
    23→            if (defined $child && !ref($child) && $child eq '=') {
    24→                $has_init = 1;
    25→                $equals_index = $i;
    26→                last;
    27→            }
    28→        }
    29→
    30→        unless ($has_init && $builder) {
    31→            # No initialization or no builder - just return undef for now
    32→            # TODO: Handle uninitialized declarations
    33→            return undef;
    34→        }
    35→
    36→        # Get the variable (child 2)
    37→        my $var = $context->child(2);
    38→
    39→        # Extract variable name from metadata hashref
    40→        my $var_name;
    41→        if (ref($var) eq 'HASH' && $var->{type} eq 'scalar_var') {
    42→            $var_name = $var->{name};
