        my $self_span = $self->context->end_pos - $self->context->start_pos;
        my $other_span = $other->context->end_pos - $other->context->start_pos;

        # Debug - show all comparisons
        my $self_start = $self->context->start_pos;
        my $self_end = $self->context->end_pos;
        my $other_start = $other->context->start_pos;
        my $other_end = $other->context->end_pos;
        my $rule = $self->context->rule || 'unknown';
        if ($self_span != $other_span) {
            warn "Semiring add: $rule\n";
            warn "  self: span=$self_span ($self_start->$self_end)\n";
            warn "  other: span=$other_span ($other_start->$other_end)\n";
        }

        if ($other_span > $self_span) {
            warn "  -> choosing other (longer span)\n" if $self_span != $other_span;
            return $other;  # Other consumed more input, prefer it
        }
        if ($self_span > $other_span) {
            warn "  -> choosing self (longer span)\n" if $self_span != $other_span;
            return $self;  # Self consumed more input, prefer it
        }

