            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef
        );

        my $empty_ctx_add = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => 0,
            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef
        );

