use 5.42.0;
use lib 'lib';
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::IR::Builder;
use Chalk::Semiring::Semantic;

# Load grammar
open my $fh, '<:utf8', 'grammar/chalk.bnf' or die $!;
my $bnf_content = do { local $/; <$fh> };
close $fh;

my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');

# Create IR builder
my $builder = Chalk::IR::Builder->new();
$builder->build_start_node('test_assignment', ['i']);

# Create environment
my %env = ( ir_builder => $builder );
my $semiring = Chalk::Semiring::Semantic->new(env => \%env, grammar => $grammar);
my $parser = Chalk::Parser->new(grammar => $grammar, semiring => $semiring);

# Test just the assignment
print "Test: assignment alone\n";
print "Parsing: \$i = \$i - 1\n\n";

my $result = $parser->parse_string('$i = $i - 1');

if ($result) {
    print "Parse succeeded!\n";
    my $graph = $builder->graph;

    print "\nNodes created:\n";
    for my $node_id (sort keys %{$graph->nodes}) {
        my $node = $graph->nodes->{$node_id};
        print "  $node_id: ", $node->op;
        if ($node->op eq 'Constant') {
            print " (value: ", $node->attributes->{value}, ")";
        } elsif ($node->op eq 'Store') {
            print " (name: ", $node->attributes->{name}, ", value_node: ", $node->attributes->{value}{node_id}, ")";
        } elsif ($node->op eq 'Load') {
            print " (name: ", $node->attributes->{name}, ")";
        }
        print "\n";
    }
} else {
    print "Parse failed!\n";
}

