     1→# ABOUTME: Boolean semiring for fast parse validation without position tracking
     2→# ABOUTME: Provides simple true/false parsing for syntax checking similar to perl -c
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Base;
     7→
     8→class Chalk::Semiring::BooleanElement :isa(Chalk::Element) {
     9→    field $value :param :reader;
    10→
    11→    method add( $other, $swap = undef ) {
    12→        # Boolean OR for choice: either can succeed
    13→        return Chalk::Semiring::BooleanElement->new(
    14→            value => $value || $other->value
    15→        );
    16→    }
    17→
    18→    method multiply( $other, $swap = undef ) {
    19→        # Boolean AND for sequence: both must succeed
    20→        return Chalk::Semiring::BooleanElement->new(
    21→            value => $value && $other->value
    22→        );
    23→    }
    24→
    25→    method equals( $other, $swap = undef ) {
    26→        return 0 unless ref($other) eq ref($self);
    27→        return $value == $other->value;
    28→    }
    29→
    30→    method score() {
    31→        return $value;
    32→    }
    33→
    34→    method to_string(@args) {
    35→        return $value ? '1' : '0';
    36→    }
    37→}
    38→
    39→class Chalk::Semiring::Boolean :isa(Chalk::Semiring) {
